CREATE OR REPLACE FUNCTION trip_private.legal_dob_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_created timestamptz; BEGIN IF auth.uid() IS NOT NULL THEN IF NEW.user_id <> auth.uid() THEN RAISE EXCEPTION 'Not your birthday'; END IF; IF NOT trip_private.legal_current(NEW.user_id) THEN RAISE EXCEPTION 'Please agree to the current Terms before continuing'; END IF; SELECT created_at INTO v_created FROM auth.users WHERE id=NEW.user_id; IF v_created >= timestamptz '2026-10-02 19:18:00+00' AND extract(year FROM age(current_date, NEW.dob)) < 18 THEN RAISE EXCEPTION 'You must be 18 or older to create an account'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER player_private_legal_age BEFORE INSERT ON public.player_private FOR EACH ROW EXECUTE FUNCTION trip_private.legal_dob_guard();